function showEscalationTrackingIcon(showIcon) {
			var e = gel('esc_tracking_50a9ed33c38013103d62fe53e40131b7:incident.assignment_group');
			if (showIcon) {
				e.classList.remove('hide-oc-live-esc-icon');
